// CSD_RATIONALE_BEGIN
// The key insight from the feedback: syntax is 59.2% because the constrained branch
// is almost never triggered (only 3/49 examples). The model generates "<<" freely
// but the strategy was waiting for a reactive trigger that rarely matched.
//
// Fix: FORCE span entry. Instead of waiting for the model to emit "<<", we use
// UnconstrainedChunk to generate until "<<" is observed (stoppedOnOpenSpan),
// then immediately enter constrained mode. If "<<" is already in the output,
// we use EnterObservedConstrainedSpan. If the chunk ends without "<<", we
// check if "<<" was the last token in the generated output.
//
// Inside the span, we use SafeSoftConstrainedStep which:
//   - Tries the model's top token first (preserving accuracy)
//   - Falls back to hard parser masking only when the model's choice is invalid
// This balances accuracy (model's reasoning) with syntax (grammar enforcement).
//
// The strategy:
//   1. Outside span: use UnconstrainedChunk with "<<" as the stop token.
//      If stoppedOnOpenSpan, enter constrained mode immediately.
//   2. Inside span (not complete): use SafeSoftConstrainedStep to generate
//      parser-valid tokens with the model's preferred choices.
//   3. Inside span (complete): close with CloseConstrainedSpan.
//
// This ensures every "<<" in the output is followed by constrained content,
// driving syntax rate up while keeping accuracy via soft gating.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   1. Outside-span branch (UnconstrainedChunk): if stoppedOnOpenSpan is true,
//      generatedOut already ends with "<<" and we call EnterObservedConstrainedSpan
//      which sets currentConstrainedOut := [] (valid by precondition parser.IsValidPrefix([])).
//      If not stoppedOnOpenSpan, we check if the last token is "<<" and enter similarly.
//      Otherwise insideConstrainedOut stays false, keeping the implication vacuous.
//   2. Complete-prefix branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//      making the implication vacuous after the call.
//   3. Active constrained branch: SafeSoftConstrainedStep returns either eosToken or a
//      parser-valid next token (by its postcondition). AppendConstrainedToken appends
//      that token to both generated and currentConstrainedOut, preserving
//      parser.IsValidPrefix(currentConstrainedOut) by the parser's prefix-extension property.
//
// progress:
//   1. Outside-span branch: UnconstrainedChunk costs stepsUsed >= 1, and generatedOut
//      is already extended by stepsUsed tokens at most. steps += stepsUsed, so
//      |generated| <= |generatedPrefix| + steps is preserved.
//   2. Complete-prefix branch: steps += 1, CloseConstrainedSpan appends ">>" (1 token).
//      |generated| grows by 1 <= 1. Preserved.
//   3. Active constrained branch: steps += 1, AppendConstrainedToken appends at most 1 token
//      (or we break on EOS with no append). |generated| grows by at most 1 <= 1. Preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve the math problem step by step. For EVERY arithmetic expression and the final answer, you MUST use << >> delimiters. Example: <<3+4=7>>. End with #### <<final_answer>>. Every << must be closed with >>.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Use UnconstrainedChunk to generate until "<<" is observed or budget exhausted
    var chunkBudget: nat := if maxSteps - steps < 30 then maxSteps - steps else 30;
    if chunkBudget == 0 {
      break;
    }
    var generatedOut, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := generatedOut;
    steps := steps + stepsUsed;
    if stoppedOnEos {
      break;
    } else if stoppedOnOpenSpan {
      // "<<" is already in generated, enter constrained mode
      var g2, ins2, cur2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := ins2;
      currentConstrainedOut := cur2;
    } else {
      // Check if the last token is "<<" (chunk ended at budget but last token was "<<")
      if |generated| > 0 && generated[|generated| - 1] == "<<" {
        var g2, ins2, cur2 := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := g2;
        insideConstrainedOut := ins2;
        currentConstrainedOut := cur2;
      }
      // Otherwise we're still outside, loop will continue
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next, usedFallback := helpers.SafeSoftConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, 8.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

